/** mcpb/manifest.json must describe exactly what the server serves (generated by scripts/gen-mcpb-manifest.ts). */
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { catalogue } from '../../src/catalogue.js';
import { ROOT } from '../helpers.js';

const manifest = JSON.parse(readFileSync(path.join(ROOT, 'mcpb', 'manifest.json'), 'utf8')) as {
  version: string;
  tools: Array<{ name: string; description: string }>;
  prompts: Array<{ name: string; description: string; arguments: string[]; text: string }>;
  server: { mcp_config: { env: Record<string, string> } };
};
const pkg = JSON.parse(readFileSync(path.join(ROOT, 'package.json'), 'utf8')) as { version: string };
const DETAILS_SUFFIX = '\n\n---\nThe user says: ${arguments.details}';

describe('mcpb/manifest.json matches the server registry', () => {
  const cat = catalogue();

  it('tools: same names, same order, same descriptions', () => {
    expect(manifest.tools).toEqual(cat.tools);
  });

  it('prompts: same names, descriptions and text, with the details argument', () => {
    expect(manifest.prompts.map((p) => p.name)).toEqual(cat.prompts.map((p) => p.name));
    for (const p of cat.prompts) {
      const m = manifest.prompts.find((x) => x.name === p.name)!;
      expect(m.description).toBe(p.description);
      expect(m.arguments).toEqual(['details']);
      expect(m.text).toBe(p.text + DETAILS_SUFFIX);
    }
  });

  it('version matches package.json, and the env vars are the ones the server reads', () => {
    expect(manifest.version).toBe(pkg.version);
    expect(cat.version).toBe(pkg.version);
    expect(Object.keys(manifest.server.mcp_config.env).sort()).toEqual(['CTRLSTREAM_DIR', 'CTRLSTREAM_OBS_HOST', 'CTRLSTREAM_OBS_PASSWORD', 'CTRLSTREAM_OBS_PORT']);
  });
});
